	ТекущиеДанные = Элементы.ПСЭ_Предшественники.ТекущиеДанные;
	упо_ЭлементыСтруктурВерсийПлановКлиент.ОткрытьЭлемент(ТекущиеДанные.ПредшественникУИД);
