&НаКлиенте
Процедура ОбновитьЭлементыДлительности()

	ДоступнаНулеваяДлительность = ДоступнаНулеваяДлительность(ВидЭлемента, План);

	Элементы.ЕдиницаИзмеренияДлительности.АвтоОтметкаНезаполненного = Не ДоступнаНулеваяДлительность; 
    Элементы.ЕдиницаИзмеренияДлительности.ОтметкаНезаполненного = Не ДоступнаНулеваяДлительность;
КонецПроцедуры

&НаКлиенте
Процедура УстановитьЕдиницуВремениПоУмолчаниюЕслиНеЗаполнена()

	ЕдиницаВремениПоУмолчанию = упо_МенеджерФормыЭлементаПланаКлиентСервер.ЕдиницаВремениПоУмолчанию();
	Если Не ФиксированныеСроки И Не ЗначениеЗаполнено(ЕдиницаИзмеренияДлительности) Тогда
		ЕдиницаИзмеренияДлительности = ЕдиницаВремениПоУмолчанию;
	КонецЕсли;

КонецПроцедуры

&НаКлиенте
Процедура ЗаполнитьФормуПоОписаниюЭлемента(Отказ)

	ЗаполнитьЗначенияСвойств(ЭтотОбъект, ОбъектФормы.ЭлементПлана);

	ПредшественникиЭлемента = ОбъектФормы.ПредшественникиЭлемента;
	Для Каждого Предшественник Из ПредшественникиЭлемента Цикл
		ОписаниеСвязи = ПСЭ_Предшественники.Добавить();
		ЗаполнитьЗначенияСвойств(ОписаниеСвязи, Предшественник);
	КонецЦикла;

	ВнешниеПредшественникиЭлемента = ОбъектФормы.ВнешниеПредшественникиЭлемента;
	Для Каждого ВнешнийПредшественник Из ВнешниеПредшественникиЭлемента Цикл
		ОписаниеСвязи = ПСЭ_ВнешниеПредшественники.Добавить();
		ЗаполнитьЗначенияСвойств(ОписаниеСвязи, ВнешнийПредшественник);
		ОписаниеСвязи.Наименование = упо_МенеджерФормыЭлементаПланаВызовСервера.ПредставлениеВнешнейСвязи(
			ВнешнийПредшественник);
	КонецЦикла;

	ВнешниеПоследователиЭлемента = ОбъектФормы.ВнешниеПоследователиЭлемента;
	ОписаниеВнешнейСвязиДляФормированияПредставления = Новый Структура("ПланПредшественника, СценарийПредшественника,
		|ВерсияПланаПредшественника, ПредшественникУИД");
	Для Каждого ВнешнийПоследователь Из ВнешниеПоследователиЭлемента Цикл
		ОписаниеСвязи = ПСЭ_ВнешниеПоследователи.Добавить();
		ЗаполнитьЗначенияСвойств(ОписаниеСвязи, ВнешнийПоследователь);
		ОписаниеСвязи.ПоследовательУИД = ОписаниеСвязи.ЭлементУИД;
		ОписаниеСвязи.ЭлементУИД = ЭлементУИД;
		ОписаниеВнешнейСвязиДляФормированияПредставления.ВерсияПланаПредшественника = ОписаниеСвязи.ВерсияПлана;
		ОписаниеВнешнейСвязиДляФормированияПредставления.ПредшественникУИД = ОписаниеСвязи.ПоследовательУИД;
		ОписаниеСвязи.Наименование = упо_МенеджерФормыЭлементаПланаВызовСервера.ПредставлениеВнешнейСвязи(
			ОписаниеВнешнейСвязиДляФормированияПредставления);
	КонецЦикла;

	Если ЗначениеЗаполнено(МассивЭлементовПлана) Тогда
		ЭлементыПланаСИдентификаторами = ПолучитьНаименованияИ_УИДыЭлементовПоМассиву(МассивЭлементовПлана);
	ИначеЕсли ВладелецФормы <> Неопределено И ВладелецФормыМожетВернутьДеревоЭлементов Тогда
		//ДеревоЭлементовПлана = ВладелецФормы.ПолучитьдеревоЭлементовПлана(ВерсияПлана);
		//ЭлементыПланаСИдентификаторами = 
		//	упо_МенеджерФормыЭлементаПланаКлиент.ПолучитьНаименованияИ_УИДыЭлементовПоДеревуЭлементов(
		//	ДеревоЭлементовПлана);
	Иначе
		ОбщийМодуль = упо_ЭлементыСтруктурВерсийПлановВызовСервера;
		ЭлементыПланаСИдентификаторами = ОбщийМодуль.ПолучитьНаименованияИ_УИДыЭлементовВерсииПлана(ВерсияПлана);
	КонецЕсли;

	НаименованиеРодителя = ЭлементыПланаСИдентификаторами.УИД_Наименование.Получить(РодительУИД);

	Для Каждого Связь Из ПСЭ_Предшественники Цикл
		Связь.Наименование = ЭлементыПланаСИдентификаторами.УИД_Наименование.Получить(Связь.ПредшественникУИД);
	КонецЦикла;

	ПодчиненныйПланПредставление = упо_ТрансляцияДанныхКлиентСервер.ПредставлениеПодчиненногоПлана(ПодчиненныйПлан,
		ПодчиненныйСценарийПланирования, ПодчиненнаяВерсияПлана, ПодчиненныйЕдиныйЭлементУИД);

	ВерхнеуровневаяЗадачаПредставление = упо_ТрансляцияДанныхКлиентСервер.ПредставлениеПодчиненногоПлана(
		ПланВерхнегоУровня, СценарийПланированияВерхнегоУровня, ВерсияПланаВерхнегоУровня, 
		ЕдиныйЭлементУИДВерхнегоУровня);

	ЗадачиНижнегоУровня.Параметры.УстановитьЗначениеПараметра("ЕдиныйЭлементУИДВерхнегоУровня", ЕдиныйЭлементУИД);
	ЗадачиНижнегоУровня.Параметры.УстановитьЗначениеПараметра("ПланВерхнегоУровня", План);
КонецПроцедуры

&НаКлиенте
Функция ПолучитьНаименованияИ_УИДыЭлементовПоМассиву(Знач МассивЭлементовПлана)

	ЭлементыПланаСИдентификаторами = 
		упо_ЭлементыСтруктурВерсийПлановКлиентСервер.НоваяСтруктураЭлементыПланаСИдентификаторами();
	Наименование_УИД = ЭлементыПланаСИдентификаторами.Наименование_УИД;
	УИД_Наименование = ЭлементыПланаСИдентификаторами.УИД_Наименование;

	Для Каждого ЭлементМассива Из МассивЭлементовПлана Цикл
		Наименование_УИД.Вставить(ЭлементМассива.Наименование, ЭлементМассива.ЭлементУИД);
		УИД_Наименование.Вставить(ЭлементМассива.ЭлементУИД, ЭлементМассива.Наименование);
	КонецЦикла;

	Возврат ЭлементыПланаСИдентификаторами;

КонецФункции

&НаКлиенте
Процедура ЗаполнитьСтрокуПоВыбранномуЗначению(ВыбранноеЗначение)

	СтрокаТаблицы = Элементы.ПСЭ_Предшественники.ТекущиеДанные;
	СтрокаТаблицы.ПредшественникУИД = ВыбранноеЗначение.ЭлементУИД;
	СтрокаТаблицы.Наименование = ВыбранноеЗначение.Наименование;
	Если Не ЗначениеЗаполнено(СтрокаТаблицы.ТипСвязи) Тогда
		СтрокаТаблицы.ТипСвязи = упо_МенеджерФормыЭлементаПланаКлиентСервер.ТипСвязиПоУмолчанию();
	КонецЕсли;
	Если Не ЗначениеЗаполнено(СтрокаТаблицы.ЕдиницаВремениСмещения) Тогда
		СтрокаТаблицы.ЕдиницаВремениСмещения = упо_МенеджерФормыЭлементаПланаКлиентСервер.ЕдиницаВремениПоУмолчанию();
	КонецЕсли;
КонецПроцедуры

&НаКлиентеНаСервереБезКонтекста
Функция ПодготовитьПредставлениеПланаИВерсии(План, ВерсияПлана)

	ПланФорматированнаяСтрока = ПолучитьФорматированнуюСтрокуСоСсылкой(План);
	ВерсияФорматированнаяСтрока = ПолучитьФорматированнуюСтрокуСоСсылкой(ВерсияПлана);
	Представление = Новый ФорматированнаяСтрока(ПланФорматированнаяСтрока, " (", ВерсияФорматированнаяСтрока, ")");
	Возврат Представление;
КонецФункции

&НаКлиентеНаСервереБезКонтекста
Функция ПолучитьФорматированнуюСтрокуСоСсылкой(СсылкаНаОбъект)

	Ссылка = ПолучитьНавигационнуюСсылку(СсылкаНаОбъект);
	Представление = Строка(СсылкаНаОбъект);
	ФорматированнаяСтрока = Новый ФорматированнаяСтрока(Представление, , , , Ссылка);

	Возврат ФорматированнаяСтрока;
КонецФункции

&НаКлиенте
Процедура ДополнительныеСведенияЗавершение(ДанныеДопСведения, ДопПараметры) Экспорт

	Если ДанныеДопСведения = Неопределено Тогда
		Возврат;
	КонецЕсли;

	ДанныеДопСвойств = ДополнительныеСвойства.ДанныеДопСвойств;

	Для Каждого ОписаниеСвойства Из ДополнительныеСвойства.ОписанияСвойств Цикл
		ОписаниеДопСвойства = ОписаниеСвойства.Значение;
		Если Не ОписаниеДопСвойства.ЭтоДополнительноеСведение Тогда
			Продолжить;
		КонецЕсли;
		Если ДанныеДопСвойств[ОписаниеДопСвойства.Имя] <> ДанныеДопСведения.Получить(ОписаниеДопСвойства.Свойство) Тогда
			ДанныеДопСвойств[ОписаниеДопСвойства.Имя] = ДанныеДопСведения.Получить(ОписаниеДопСвойства.Свойство);
			Модифицированность = Истина;
		КонецЕсли;
	КонецЦикла;

КонецПроцедуры

&НаСервере
Процедура ИнициализироватьОписанияДопРеквизитовИСведений()

	Если Не Параметры.Свойство("ДопРеквизитыИСведения", ДополнительныеСвойства)
		Или Не ДополнительныеСвойства.Свойство("Использовать") Тогда

		ДополнительныеСвойства = Новый Структура("Использовать", Ложь);
		Возврат;
	КонецЕсли;

	ДанныеДопСвойств = Новый Структура();

	Для Каждого ОписаниеСвойства Из ДополнительныеСвойства.ОписанияСвойств Цикл
		ДанныеДопСвойств.Вставить(ОписаниеСвойства.Ключ);
	КонецЦикла;

	ЗаполнитьЗначенияСвойств(ДанныеДопСвойств, ОбъектФормы.ЭлементПлана);
	ДополнительныеСвойства.Вставить("ДанныеДопСвойств", ДанныеДопСвойств);

КонецПроцедуры

&НаКлиенте
Процедура ИнициализироватьЗначенияДополнительныхРеквизитовИСвойств() 

	Если Не ЭтотОбъект.ПараметрыСвойств.ВыполненаОтложеннаяИнициализация Тогда

		СвойстваВыполнитьОтложеннуюИнициализацию();
		УправлениеСвойствамиКлиент.ПослеЗагрузкиДополнительныхРеквизитов(ЭтотОбъект);
		Если ВладелецФормыМожетВернутьДеревоЭлементов Тогда
			ИнициализироватьЗначенияДополнительныхСвойствНаФорме();
		КонецЕсли;

		ОграничитьДоступностьЭлементовФормыДополнительныеРеквизиты();

	КонецЕсли;

КонецПроцедуры

#Область ОбработкаВыбораДляФормы

&НаКлиенте
Процедура ОбработатьВыборДляФормы(ВыбранноеЗначение)

	Если ВыбранноеЗначение.Данные = "ЕдиныйЭлементУИД" И ЕдиныйЭлементУИД <> ВыбранноеЗначение.Значение Тогда

		ЕдиныйЭлементУИД = ВыбранноеЗначение.Значение;
		ЗаполнитьФормуПоЕдиныйЭлементУИД(ВыбранноеЗначение.Значение, Истина);
		Модифицированность = Истина;

		ЗакрытьФормыСвязанныеСоСправочником();
	КонецЕсли;
КонецПроцедуры

&НаКлиенте
Процедура ЗакрытьФормыСвязанныеСоСправочником()

	СписокНеЗакрываемыхФорм = ФормыНеСвязанныеСоСправочником();

	Для Каждого Форма Из Окно.Содержимое Цикл

		Если СписокНеЗакрываемыхФорм.Найти(Форма.ИмяФормы) <> Неопределено Тогда
			Продолжить;
		КонецЕсли;

		Форма.Закрыть();
	КонецЦикла;
КонецПроцедуры

&НаКлиенте
Функция ФормыНеСвязанныеСоСправочником()

	СписокНеЗакрываемыхФорм = Новый Массив;
	СписокНеЗакрываемыхФорм.Добавить("Справочник.упо_ВерсииПланов.Форма.ФормаЭлементаСтруктуры");
	СписокНеЗакрываемыхФорм.Добавить("Справочник.упо_ВерсииПланов.Форма.ФормаСвязанныхЭлементовПлана");

	Возврат СписокНеЗакрываемыхФорм;
КонецФункции

#КонецОбласти

#Область ОтображениеФормы

&НаКлиенте
Процедура ОпределитьДоступностьПолейСроков()

	РучнойВвод = ФиксированныеСроки;
	Элементы.Начало.Доступность = РучнойВвод;
	Элементы.Завершение.Доступность = РучнойВвод;
	Элементы.ОграничениеРасчета.Доступность = Не РучнойВвод;
	ОбновитьВидимостьДатыОграничения();
КонецПроцедуры

&НаКлиенте
Процедура ПересчитатьДлительностьЗадачиПриРучномВводеСроков()

	МодульРасчета = упо_РасчетСроковКлиентСервер;

	СведенияОЕдиницеВремени = ПолучитьСведенияОЕдиницеВремени(ЕдиницаИзмеренияДлительности);
	Если Не ЗначениеЗаполнено(СведенияОЕдиницеВремени.КоличествоБазовыхЕдиниц) Тогда
		ТекстСообщения = НСтр("ru = 'Не заполнена единица измерения времени'");
		ОбщегоНазначенияКлиент.СообщитьПользователю(ТекстСообщения);
		Возврат;
	КонецЕсли;

	Если СведенияОЕдиницеВремени.Астрономическая Тогда
		РассчитатьДлительностьВАстрономическихЕдиницахВремени(МодульРасчета);
	Иначе
		РассчитатьДлительностьВРабочихЕдиницахВремени(МодульРасчета, СведенияОЕдиницеВремени);
	КонецЕсли;

	ОформитьКолонкиЗависимыеОтДругихЗадач();
КонецПроцедуры

&НаКлиенте
Процедура РассчитатьДлительностьВАстрономическихЕдиницахВремени(МодульРасчета)

	ЕдиницаИзмеренияДлительности = ПредопределенноеЗначение("Справочник.упо_ЕдиницыВремени.АЧас");
	Час = упо_ОбщиеПроцедурыРасчетаСроковКлиентСервер.СекундВЧасе();
	ДлительностьВСекундах = Завершение - Начало;
	Если ДлительностьВСекундах <= 0 Тогда
		Длительность = 0;
		Возврат;
	КонецЕсли;
	Длительность = ДлительностьВСекундах / Час;
КонецПроцедуры

&НаКлиенте
Процедура РассчитатьДлительностьВРабочихЕдиницахВремени(МодульРасчета, СведенияОЕдиницеВремени)

	ЗаполнитьДанныеКалендаряПриНеобходимости();
	Если Не ЗначениеЗаполнено(ДанныеКалендаря) Тогда
		Возврат;
	КонецЕсли;

	ДлительностьВСекундах = МодульРасчета.РабочихСекундВПериоде(Начало, Завершение, ДанныеКалендаря);

	Если ДлительностьВСекундах <= 0 Тогда
		Длительность = 0;
		Возврат;
	КонецЕсли;

	Длительность = ДлительностьВСекундах / СведенияОЕдиницеВремени.КоличествоБазовыхЕдиниц;

КонецПроцедуры

&НаКлиенте
Процедура ЗаполнитьДанныеКалендаряПриНеобходимости(Календарь = Неопределено)

	Если Не ЗначениеЗаполнено(Календарь) Тогда
		Календарь = ОпределитьКалендарь();
		Если Не ЗначениеЗаполнено(Календарь) Тогда
			Возврат;
		КонецЕсли;
	КонецЕсли;

	Если Не ЗначениеЗаполнено(ДанныеКалендаря) Или КалендарьИзменен Тогда
		ДанныеКалендаря = упо_ОбщиеПроцедурыРасчетаСроковКлиентСервер.ДанныеКалендаряПоСсылке(Календарь);
		КалендарьИзменен = Ложь;
	КонецЕсли;

КонецПроцедуры

&НаСервереБезКонтекста
Функция ПолучитьСведенияОЕдиницеВремени(ЕдиницаИзмеренияДлительности)

	РеквизитыЕдиницыВремени = "Астрономическая, БазоваяАстрономическаяЕдиница, КоличествоБазовыхЕдиниц";
	Возврат ОбщегоНазначения.ЗначенияРеквизитовОбъекта(ЕдиницаИзмеренияДлительности, РеквизитыЕдиницыВремени);

КонецФункции

&НаКлиенте
Функция ОпределитьКалендарь()

	Если ЗначениеЗаполнено(Календарь) Тогда
		Возврат Календарь;
	КонецЕсли;

	КалендарьПлана = ПолучитьКалендарьПлана(План);

	Если ЗначениеЗаполнено(КалендарьПлана) Тогда
		Возврат КалендарьПлана;
	Иначе
		Календарь = упо_КалендариКлиентСервер.КалендарьПоУмолчанию();

		Если Не ЗначениеЗаполнено(Календарь) Тогда
			ТекстСообщения = НСтр("ru = 'Не удалось определить календарь'");
			ОбщегоНазначенияКлиент.СообщитьПользователю(ТекстСообщения);
		КонецЕсли;

		Возврат Календарь;
	КонецЕсли;

КонецФункции

&НаСервереБезКонтекста
Функция ПолучитьКалендарьПлана(План)
	Возврат ОбщегоНазначения.ЗначениеРеквизитаОбъекта(План, "Календарь");
КонецФункции

&НаКлиенте
Процедура УстановитьЗаголовок(Форма)

	Форма.Заголовок = Наименование;

КонецПроцедуры

&НаКлиенте
Процедура ОбновитьВидимостьДатыОграничения()

	Если НадоОтобразитьДатуОграничения(ОграничениеРасчета) Тогда
		Элементы.ДатаОграничения.Видимость = Истина;
	Иначе
		ДатаОграничения = Дата(1, 1, 1);
		Элементы.ДатаОграничения.Видимость = Ложь;
	КонецЕсли;

КонецПроцедуры

&НаКлиентеНаСервереБезКонтекста
Функция НадоОтобразитьДатуОграничения(Ограничение)

	Если Не ЗначениеЗаполнено(Ограничение) 
		Или Ограничение = ПредопределенноеЗначение("Перечисление.упо_ТипыОграниченийСроковЭлементов.КакМожноРаньше") 
		Или Ограничение = ПредопределенноеЗначение("Перечисление.упо_ТипыОграниченийСроковЭлементов.КакМожноПозже") Тогда
		Возврат Ложь;
	Иначе
		Возврат Истина;
	КонецЕсли;

КонецФункции

#КонецОбласти

#Область ЕдиныйЭлементУИД

&НаСервере
Процедура ЗаполнитьФормуПоЕдиныйЭлементУИД(УИДЕдиногоЭлемента, ОбновлениеЭлемента = Ложь)

	ОбъектЕдиногоЭлементаПлана = упо_ЕдиныеЭлементыПланаВызовСервера.ПолучитьОбъектЕдиногоЭлементаПлана(
		УИДЕдиногоЭлемента);

	ЗаполнитьРеквизитОбъект();

	Если ОбновлениеЭлемента Тогда
		// СтандартныеПодсистемы.Свойства
		УправлениеСвойствами.ЗаполнитьДополнительныеРеквизитыВФорме(ЭтотОбъект);
		// СтандартныеПодсистемы.Свойства
	КонецЕсли;

	ДоступностьЭлементовУправленияПоОбъекту();
КонецПроцедуры

&НаСервере
Процедура ЗаполнитьРеквизитОбъект()
	Если ЗначениеЗаполнено(ОбъектЕдиногоЭлементаПлана) Тогда
		ЗначениеВРеквизитФормы(ОбъектЕдиногоЭлементаПлана.ПолучитьОбъект(), "Объект");
	Иначе
		// для обновления дополнительных реквизитов
		ЗначениеВРеквизитФормы(Справочники.упо_ОбъектыЕдиныхЭлементовСтруктурПланов.СоздатьЭлемент(), "Объект");
	КонецЕсли;
КонецПроцедуры

&НаСервере
Процедура ДоступностьЭлементовУправленияПоОбъекту()

	ОбъектСоздан = ЗначениеЗаполнено(ОбъектЕдиногоЭлементаПлана);
	Если Не ВладелецФормыМожетВернутьДеревоЭлементов Тогда
		Элементы.ГруппаДополнительныеРеквизиты.Видимость = ОбъектСоздан;
		Элементы.ФормаЗаполнитьДополнительныеРеквизиты.Видимость = Не ОбъектСоздан;
	КонецЕсли;

	ИспользоватьДополнительныеРеквизитыИСведения = Константы.ИспользоватьДополнительныеРеквизитыИСведения.Получить();

	ИспользоватьДопРеквизиты = ИспользоватьДополнительныеРеквизитыИСведения И Не ОбъектСоздан
		И УправлениеСвойствами.СвойстваОбъекта(Объект, Истина, Ложь).Количество() > 0;
	ИспользоватьДопСвойства = ИспользоватьДополнительныеРеквизитыИСведения 
		И УправлениеСвойствами.СвойстваОбъекта(Объект, Ложь, Истина).Количество() > 0;

	//Элементы.ФормаЗаполнитьДополнительныеРеквизиты.Видимость = ИспользоватьДопРеквизиты;
	Элементы.ФормаДополнительныеСведения.Видимость = ИспользоватьДопСвойства;

	ИспользуютсяПодчиненныеПланы = упо_УправлениеКонфигурациейВызовСервера.ИспользуютсяПодчиненныеПланы();
	ДоступныПодчиненныеПланы = упо_УправлениеКонфигурациейВызовСервера.
		ПодчиненныеПланыДоступны(ОбъектФормы.ЭлементПлана.План);
	Элементы.ПодчиненныйПланПредставление.Видимость = ИспользуютсяПодчиненныеПланы И ДоступныПодчиненныеПланы;

	ДоступненСводныйСтатусОтчет = упо_УправлениеКонфигурациейКлиентСервер.ДоступноИспользованиеСводныйСтатусОтчет();
	Элементы.ВыводитьВСводныйСтатусОтчет.Видимость = ДоступненСводныйСтатусОтчет;

КонецПроцедуры

#КонецОбласти

#Область ЗаписьДанных

&НаКлиенте
Функция ЗаписатьДанныеЭлементаКлиент(Отказ)

	Если Не Модифицированность Тогда
		Возврат Неопределено;
	КонецЕсли;

	ПередЗаписьюНаКлиенте(Отказ);

	ЗаписатьНаСервере(Отказ);

	Если Отказ Тогда
		Возврат Неопределено;
	КонецЕсли;

	ЗначенияВсехДопСвойств = ПолучитьДанныеВсехДополнительныхСвойств();

	ИзмененияОбъектаФормы = упо_МенеджерФормыЭлементаПланаКлиент.НовыйРезультатЗакрытияФормы();
	ИзмененияОбъектаФормы.ЭлементУИД = ЭлементУИД;
	ИзмененияОбъектаФормы.ВерсияПлана = ВерсияПлана;

	ПроверитьИзменениеСвойствЭлемента(ИзмененияОбъектаФормы, ЗначенияВсехДопСвойств);
	упо_МенеджерФормыЭлементаПланаКлиент.ПроверитьИзменениеСвязейВФорме(ЭтотОбъект, ИзмененияОбъектаФормы);

	Модифицированность = Ложь;

	Возврат ИзмененияОбъектаФормы;
КонецФункции

&НаКлиенте
Процедура ПроверитьИзменениеСвойствЭлемента(ИзмененияОбъектаФормы, ЗначенияВсехДопСвойств)

	ЭлементПлана = ИзмененияОбъектаФормы.ЭлементПлана;
	ЗаполнитьЗначенияСвойств(ЭлементПлана, ЭтотОбъект);

	Для Каждого КлючЗначение Из ЗначенияВсехДопСвойств Цикл
		ЭлементПлана.Вставить(КлючЗначение.Ключ, КлючЗначение.Значение);
	КонецЦикла;

	// Сравниваем новые значения со старыми, если совпадают, удаляем свойство.
	// так, в результате будет массив с изменившимися значениями 
	ИсходноеОписаниеЭлемента = ОбъектФормы.ЭлементПлана;
	Для Каждого НовыеЗначения Из ЭлементПлана Цикл

		ИмяСвойства = НовыеЗначения.Ключ;

		Если ИсходноеОписаниеЭлемента[ИмяСвойства] = НовыеЗначения.Значение Тогда
			ЭлементПлана.Удалить(ИмяСвойства);
		КонецЕсли;

	КонецЦикла;
	Если ЭлементПлана.Количество() > 0 Тогда
		ИзмененияОбъектаФормы.СвойстваЭлементаИзменены = Истина;
	КонецЕсли;

КонецПроцедуры

&НаКлиенте
Процедура ПередЗаписьюНаКлиенте(Отказ)

	УстановитьЕдиницуВремениПоУмолчаниюЕслиНеЗаполнена();

	ЕдиницаВремениПоУмолчанию = упо_МенеджерФормыЭлементаПланаКлиентСервер.ЕдиницаВремениПоУмолчанию();
	Для Каждого Связь Из ПСЭ_Предшественники Цикл
		Если Связь.СмещениеВЕдИзмерения <> 0 И Не ЗначениеЗаполнено(Связь.ЕдиницаВремениСмещения) Тогда
			Связь.ЕдиницаВремениСмещения = ЕдиницаВремениПоУмолчанию;
		КонецЕсли;
	КонецЦикла;

КонецПроцедуры

&НаСервере
Процедура ЗаписатьНаСервере(Отказ)

	ПередЗаписьюНаСервере(Отказ);

	ЗаполнитьКлючАналитики();
	Если Не ЗначениеЗаполнено(ЕдиныйЭлементУИД) Тогда
		ЕдиныйЭлементУИД = упо_ЭлементыСтруктурВерсийПланов.НовыйУникальныйИдентификаторЭлемента();
	КонецЕсли;

	Возврат;

КонецПроцедуры

&НаСервере
Процедура ПередЗаписьюНаСервере(Отказ)

	ТипОбъектЕдиногоЭлемента = Тип("СправочникОбъект.упо_ОбъектыЕдиныхЭлементовСтруктурПланов");
	ОбъектЕдиногоЭлементаЗапись = РеквизитФормыВЗначение("Объект", ТипОбъектЕдиногоЭлемента);

	Если Не ВладелецФормыМожетВернутьДеревоЭлементов Тогда
		// СтандартныеПодсистемы.Свойства
		УправлениеСвойствами.ПередЗаписьюНаСервере(ЭтотОбъект, ОбъектЕдиногоЭлементаЗапись);
		// Конец СтандартныеПодсистемы.Свойства       
	КонецЕсли;

	// ИнтеграцияС1СДокументооборотом
	ИнтеграцияС1СДокументооборотБазоваяФункциональность.
		ПередЗаписьюНаСервере(ЭтотОбъект, ОбъектЕдиногоЭлементаЗапись, Неопределено);
	// Конец ИнтеграцияС1СДокументооборотом

	ОбъектЕдиногоЭлементаЗапись.Записать();
	ЗначениеВРеквизитФормы(ОбъектЕдиногоЭлементаЗапись, "Объект");

КонецПроцедуры

&НаКлиенте
Процедура ПроверкаЗаполненияОбязательныхРеквизитов(Отказ)
	Если Не ЗначениеЗаполнено(ОпцииРасчета) Тогда
		Сообщение = Новый СообщениеПользователю();
		Сообщение.Текст = НСтр("ru = 'Поле ""Опция расчета"" не заполнено.'");
		Сообщение.Поле = "ОпцииРасчета";
		Сообщение.УстановитьДанные(ЭтотОбъект);
		Сообщение.Сообщить();
		Отказ = Истина;
	КонецЕсли; 

	ДоступнаНулеваяДлительность = ДоступнаНулеваяДлительность(ВидЭлемента, План);

	Если Не ДоступнаНулеваяДлительность И Не ЗначениеЗаполнено(ЕдиницаИзмеренияДлительности) Тогда
		Сообщение = Новый СообщениеПользователю();
		Сообщение.Текст = НСтр("ru = 'Поле ""Единица измерения длительности"" не заполнено.'");
		Сообщение.Поле = "ЕдиницаИзмеренияДлительности";
		Сообщение.УстановитьДанные(ЭтотОбъект);
		Сообщение.Сообщить();
		Отказ = Истина;
	КонецЕсли;

КонецПроцедуры

#КонецОбласти

&НаКлиенте
Процедура СоздатьОбъектЕдиногоЭлемента(ЕдиныйЭлементУИД)

	Если Не ЗначениеЗаполнено(ЕдиныйЭлементУИД) Тогда

		ЕдиныйЭлементУИД = упо_ЭлементыСтруктурВерсийПлановВызовСервера.НовыйУникальныйИдентификаторЭлемента();
	КонецЕсли;

	РезультатСоздания = упо_ЕдиныеЭлементыПланаВызовСервера.СоздатьЭлементСправочникаОбъектыЕдиныхЭСП(ЕдиныйЭлементУИД,
		План);
	Если Не РезультатСоздания.Успешно Тогда
		ОбщегоНазначенияКлиент.СообщитьПользователю(РезультатСоздания.ТекстОшибки);
		Возврат;
	КонецЕсли;

	ОбъектЕдиногоЭлементаПлана = РезультатСоздания.Ссылка;
	ЗаполнитьРеквизитОбъект();
	ОбновленЕдиныйЭлементУИД = Истина;
	Модифицированность = Истина;

	ЗаполнитьДопРеквизитыНаСервере();

	ДоступностьЭлементовУправленияПоОбъекту();
КонецПроцедуры

&НаСервере
Процедура ЗаполнитьДопРеквизитыНаСервере()
	// СтандартныеПодсистемы.Свойства
	УправлениеСвойствами.ЗаполнитьДополнительныеРеквизитыВФорме(ЭтотОбъект);
	// СтандартныеПодсистемы.Свойства
КонецПроцедуры

#Область ОформлениеРасчетныхПолей

&НаКлиенте
Процедура ОформитьКолонкиЗависимыеОтДругихЗадач()

	ОформляемыеЭлементы = ПолучитьПереченьЗависимыхОтДругихЗадачЭлементовФормы();
	ЦветДляОформления = ПолучитьЦветВажного();

	Для Каждого ОписаниеОформляемогоЭлемента Из ОформляемыеЭлементы Цикл

		ЭлементФормы = ОписаниеОформляемогоЭлемента.Ключ;
		ОформляемоеСвойство = ОписаниеОформляемогоЭлемента.Значение;

		Если ОформляемоеСвойство = "Рамка" Тогда
			ЭлементФормы.ЦветРамки = ЦветДляОформления;
		ИначеЕсли ОформляемоеСвойство = "Текст" Тогда
			ЭлементФормы.ЦветТекста = ЦветДляОформления;
		ИначеЕсли ОформляемоеСвойство = "Видимость" Тогда
			ЭлементФормы.Видимость = Истина;
		Иначе
			Продолжить;
		КонецЕсли;

	КонецЦикла;

КонецПроцедуры

&НаКлиенте
Функция ПолучитьПереченьЗависимыхОтДругихЗадачЭлементовФормы()

	ЭлементыНаФорме = Новый Соответствие;    
	Рамка = "Рамка";
	ЭлементыНаФорме.Вставить(Элементы.РаннееНачало, Рамка);
	ЭлементыНаФорме.Вставить(Элементы.РаннееОкончание, Рамка);
	ЭлементыНаФорме.Вставить(Элементы.ПозднееНачало, Рамка);
	ЭлементыНаФорме.Вставить(Элементы.ПозднееОкончание, Рамка);
	ЭлементыНаФорме.Вставить(Элементы.НаКритическомПути, "Текст");
	ЭлементыНаФорме.Вставить(Элементы.ПояснениеКРасчетуСроков, "Видимость");

	Возврат ЭлементыНаФорме;
КонецФункции

&НаСервереБезКонтекста
Функция ПолучитьЦветВажного()

	ЦветДляОформления = ЦветаСтиля.упо_ЦветВажногоСтильITLand;
	Возврат ЦветДляОформления;

КонецФункции

