&ИзменениеИКонтроль("ВходящиеДанныеОбъектаИС")
Функция упо_ВходящиеДанныеОбъектаИС(Прокси, СсылкаНаОбъектИС, СписокВыгружаемыхТЧ, СписокВыражений)

	ОбъектИС = СсылкаНаОбъектИС.ПолучитьОбъект();

	ОбъектМетаданных = ОбъектИС.Метаданные();

	Если Не ИнтеграцияС1СДокументооборотБазоваяФункциональность.ОбъектМетаданныхПоддерживается(ОбъектМетаданных) Тогда
		ВызватьИсключение СтрШаблон(
		НСтр("ru = 'Объект %1 (%2) не поддерживается бесшовной интеграцией. Его нельзя отправить в 1С:Документооборот.'"),
		СсылкаНаОбъектИС,
		ОбъектМетаданных.ПолноеИмя());
	КонецЕсли;

	Результат = ИнтеграцияС1СДокументооборотБазоваяФункциональность.СоздатьОбъект(Прокси, "DMIncomingData");
	Реквизиты = Результат.attributes; // СписокXDTO
	ТабличныеЧасти = Результат.tabularSections; // СписокXDTO

	// Стандартные реквизиты
	Реквизиты.Добавить(
	ПреобразоватьРеквизитОбъектаИСВОбъектXDTO(Прокси, "Представление", Строка(СсылкаНаОбъектИС)));

	ЗаполнитьРеквизитыИзМетаданных(Прокси, Реквизиты, ОбъектМетаданных.СтандартныеРеквизиты, ОбъектИС, Истина);

	// Реквизиты
	ЗаполнитьРеквизитыИзМетаданных(Прокси, Реквизиты, ОбъектМетаданных.Реквизиты, ОбъектИС);

	// Общие реквизиты
	ИспользованиеРеквизитаИспользовать = Метаданные.СвойстваОбъектов.ИспользованиеОбщегоРеквизита.Использовать;
	ИспользованиеРеквизитаАвто = Метаданные.СвойстваОбъектов.ИспользованиеОбщегоРеквизита.Авто;
	АвтоИспользованиеРеквизитаИспользовать = Метаданные.СвойстваОбъектов.АвтоИспользованиеОбщегоРеквизита.Использовать;
	РазделениеДанныхРеквизитаНеИспользовать = Метаданные.СвойстваОбъектов.РазделениеДанныхОбщегоРеквизита.НеИспользовать;

	ВсеОбщиеРеквизиты = Новый Массив;
	Для Каждого ОбщийРеквизит Из Метаданные.ОбщиеРеквизиты Цикл
		Если ОбщийРеквизит.РазделениеДанных = РазделениеДанныхРеквизитаНеИспользовать Тогда
			ВсеОбщиеРеквизиты.Добавить(ОбщийРеквизит);
		КонецЕсли;
	КонецЦикла;

	ОбщиеРеквизитыОбъекта = Новый Массив;
	Для Каждого ОбщийРеквизит Из ВсеОбщиеРеквизиты Цикл
		ЭлементСостава = ОбщийРеквизит.Состав.Найти(ОбъектМетаданных);
		Если ЭлементСостава = Неопределено Тогда
			// Общего реквизита нет в документе.
			Продолжить;
		КонецЕсли;
		Если ЭлементСостава.Использование = ИспользованиеРеквизитаИспользовать
			Или (ЭлементСостава.Использование = ИспользованиеРеквизитаАвто
			И ОбщийРеквизит.АвтоИспользование = АвтоИспользованиеРеквизитаИспользовать) Тогда
			ОбщиеРеквизитыОбъекта.Добавить(ОбщийРеквизит);
		КонецЕсли;
	КонецЦикла;

	ЗаполнитьРеквизитыИзМетаданных(Прокси, Реквизиты, ОбщиеРеквизитыОбъекта, ОбъектИС);

	// Табличные части
	Для Каждого ТабличнаяЧасть Из ОбъектМетаданных.ТабличныеЧасти Цикл

		Если ТабличнаяЧасть.Имя = "ДополнительныеРеквизиты"
			Или (ТипЗнч(СписокВыгружаемыхТЧ) = Тип("Массив")
			И СписокВыгружаемыхТЧ.Найти(ТабличнаяЧасть.Имя) = Неопределено) Тогда
			Продолжить;
		КонецЕсли;

		Колонки = Новый Массив;
		Для Каждого Реквизит Из ТабличнаяЧасть.СтандартныеРеквизиты Цикл
			Колонки.Добавить(Реквизит);
		КонецЦикла;
		Для Каждого Реквизит Из ТабличнаяЧасть.Реквизиты Цикл
			Колонки.Добавить(Реквизит);
		КонецЦикла;

		Если Колонки.Количество() = 0 Тогда
			Продолжить;
		КонецЕсли;

		ТабличныеЧасти.Добавить(
		ПреобразоватьТаблицуОбъектаИСВОбъектXDTO(
		Прокси,
		ТабличнаяЧасть.Имя,
		ОбъектИС[ТабличнаяЧасть.Имя],
		Колонки));

	КонецЦикла;

	// Данные из выражений на встроенном языке
	ЗаполнитьДанныеИзСпискаВыражений(Прокси, ОбъектИС, Реквизиты, ТабличныеЧасти, СписокВыражений);

	// Дополнительные реквизиты
	Если УправлениеСвойствами.ИспользоватьДопРеквизиты(СсылкаНаОбъектИС) Тогда
		ЗаполнитьРеквизитыИзМетаданных(
		Прокси,
		Реквизиты,
		УправлениеСвойствами.СвойстваОбъекта(СсылкаНаОбъектИС, Истина, Ложь),
		ОбъектИС,,
		Истина);
	КонецЕсли;

	#Вставка
	// {PM}
	упо_Интеграция.ДополнительнаяОбработкаВходящихДанныхОбъектаИС(Прокси, Результат, ОбъектИС, ОбъектМетаданных);
	// {/PM}
	#КонецВставки

	Возврат Результат;

КонецФункции

&ИзменениеИКонтроль("СтруктураМетаданныхИнтегрированнойСистемы")
Функция упо_СтруктураМетаданныхИнтегрированнойСистемы(Сообщение)

	Попытка

		Ответ = СоздатьОбъектБИД("DMILGetMetadataResponse");
		ОбъектыМетаданных = Ответ.metadataObjects; // СписокXDTO
		СинонимыОбъектов = Ответ.metadataSynonyms; // СписокXDTO

		ПолучатьВсе = Истина;
		ПолучатьРеквизиты = Ложь;
		ПолучатьТабличныеЧасти = Ложь;
		ПолучатьПечатныеФормы = Ложь;
		ПолучатьПравилаИнтеграции = Ложь;
		Если ИнтеграцияС1СДокументооборотБазоваяФункциональность.СвойствоУстановлено(Сообщение, "columnSet")
			И Сообщение.columnSet.Количество() > 0 Тогда
			ПолучатьВсе = Ложь;
			Для Каждого РеквизитКПолучению Из Сообщение.columnSet Цикл
				Если НРег(РеквизитКПолучению) = "objectsonly" Тогда
					ПолучатьРеквизиты = Ложь;
					ПолучатьТабличныеЧасти = Ложь;
					ПолучатьПечатныеФормы = Ложь;
					ПолучатьПравилаИнтеграции = Ложь;
					Прервать;
				ИначеЕсли НРег(РеквизитКПолучению) = "attributes" Тогда
					ПолучатьРеквизиты = Истина;
				ИначеЕсли НРег(РеквизитКПолучению) = "tabularsections" Тогда
					ПолучатьТабличныеЧасти = Истина;
				ИначеЕсли НРег(РеквизитКПолучению) = "printedforms" Тогда
					ПолучатьПечатныеФормы = Истина;
				ИначеЕсли НРег(РеквизитКПолучению) = "integrationrules" Тогда
					ПолучатьПравилаИнтеграции = Истина;
				КонецЕсли;
			КонецЦикла;
		КонецЕсли;

		Ответ.dataBaseName = ИнтеграцияС1СДокументооборотБазоваяФункциональность.СокращенноеНаименованиеКонфигурации();
		Ответ.dataBaseID = ИнтеграцияС1СДокументооборотБазоваяФункциональностьПовтИсп.ИдентификаторБазыДанных();
		Ответ.dmilVersionNumber = ИнтеграцияС1СДокументооборотБазоваяФункциональностьПовтИсп.ВерсияБИД();

		Если ИнтеграцияС1СДокументооборотБазоваяФункциональность.СвойствоУстановлено(Сообщение, "objects")
			И Сообщение.objects.Количество() > 0 Тогда
			ТипыОбъектовИС = Новый Массив;
			Для Каждого ИмяТипа Из Сообщение.objects Цикл
				Если СтрНайти(ИмяТипа, "Ссылка.") = 0 Тогда
					ИмяТипа = ИнтеграцияС1СДокументооборотБазоваяФункциональностьКлиентСервер.ИмяТипаИзПолногоИмени(ИмяТипа);
				КонецЕсли;
				ТипыОбъектовИС.Добавить(Тип(ИмяТипа));
			КонецЦикла;
		Иначе
			ТипыОбъектовИС = ИнтеграцияС1СДокументооборотБазоваяФункциональностьПовтИсп.ТипыОбъектовПоддерживающихИнтеграцию();
		КонецЕсли;

		ОбъектыПоддерживающиеИнтеграцию = Новый Массив;
		ОбщиеРеквизитыОбъектов = Новый Соответствие;
		Для Каждого ТипЗначения Из ТипыОбъектовИС Цикл
			ОбъектМетаданных = Метаданные.НайтиПоТипу(ТипЗначения);
			Если ОбъектМетаданных = Неопределено
				Или Не ИнтеграцияС1СДокументооборотБазоваяФункциональность.ОбъектМетаданныхПоддерживается(ОбъектМетаданных) Тогда
				Продолжить;
			КонецЕсли;
			ОбъектыПоддерживающиеИнтеграцию.Добавить(ОбъектМетаданных);
			ОбщиеРеквизитыОбъектов[ОбъектМетаданных] = Новый Массив;
		КонецЦикла;

		ИспользованиеРеквизитаИспользовать = Метаданные.СвойстваОбъектов.ИспользованиеОбщегоРеквизита.Использовать;
		ИспользованиеРеквизитаАвто = Метаданные.СвойстваОбъектов.ИспользованиеОбщегоРеквизита.Авто;
		АвтоИспользованиеРеквизитаИспользовать = Метаданные.СвойстваОбъектов.АвтоИспользованиеОбщегоРеквизита.Использовать;
		РазделениеДанныхРеквизитаНеИспользовать = Метаданные.СвойстваОбъектов.РазделениеДанныхОбщегоРеквизита.НеИспользовать;
		Для Каждого ОбщийРеквизит Из Метаданные.ОбщиеРеквизиты Цикл
			Если ОбщийРеквизит.РазделениеДанных <> РазделениеДанныхРеквизитаНеИспользовать Тогда
				Продолжить;
			КонецЕсли;
			Для Каждого ЭлементСостава Из ОбщийРеквизит.Состав Цикл
				Если (ЭлементСостава.Использование = ИспользованиеРеквизитаИспользовать
					Или (ЭлементСостава.Использование = ИспользованиеРеквизитаАвто
					И ОбщийРеквизит.АвтоИспользование = АвтоИспользованиеРеквизитаИспользовать))
					И ИнтеграцияС1СДокументооборотБазоваяФункциональность.ОбъектМетаданныхПоддерживается(ЭлементСостава.Метаданные)
					И ОбъектыПоддерживающиеИнтеграцию.Найти(ЭлементСостава.Метаданные) <> Неопределено Тогда
					ОбщиеРеквизитыОбъектов[ЭлементСостава.Метаданные].Добавить(ОбщийРеквизит);
				КонецЕсли;
			КонецЦикла;
		КонецЦикла;

		Синонимы = Новый Соответствие;

		Для Каждого ОбъектМетаданных Из ОбъектыПоддерживающиеИнтеграцию Цикл

			ПолноеИмя = ОбъектМетаданных.ПолноеИмя();

			ОбъектМетаданныхXDTO = СоздатьОбъектБИД("DMILMetadataObject");
			ОбъектМетаданныхXDTO.name = ПолноеИмя;
			Реквизиты = ОбъектМетаданныхXDTO.attributes; // СписокXDTO
			ТабличныеЧасти = ОбъектМетаданныхXDTO.tabularSections; // СписокXDTO
			ПравилаИнтеграции = ОбъектМетаданныхXDTO.integrationRules; // СписокXDTO

			ДобавитьСиноним(Синонимы, ПолноеИмя, ОбъектМетаданных.Синоним);

			Если ПолучатьВсе Или ПолучатьРеквизиты Тогда

				РеквизитXDTO = СоздатьОбъектБИД("DMILMetadataAttribute");
				РеквизитXDTO.name = "Представление";
				РеквизитXDTO.synonym = НСтр("ru = 'Представление'");
				ДобавитьОписаниеТиповРеквизита(РеквизитXDTO.typesList, Новый ОписаниеТипов("Строка"), Синонимы);
				Реквизиты.Добавить(РеквизитXDTO);

				ДобавитьОписаниеРеквизитов(
				Реквизиты,
				ОбъектМетаданных.СтандартныеРеквизиты,
				Синонимы,
				Истина);
				ДобавитьОписаниеРеквизитов(
				Реквизиты,
				ОбъектМетаданных.Реквизиты,
				Синонимы);
				ДобавитьОписаниеРеквизитов(
				Реквизиты,
				ОбщиеРеквизитыОбъектов[ОбъектМетаданных],
				Синонимы);

				ВладелецСвойств = Новый(ТипЗначения);
				Если УправлениеСвойствами.ИспользоватьДопРеквизиты(ВладелецСвойств) Тогда
					ДобавитьОписаниеДопРеквизитов(
					Реквизиты,
					УправлениеСвойствами.СвойстваОбъекта(ВладелецСвойств, Истина, Ложь),
					Синонимы);
				КонецЕсли;

			КонецЕсли;

			#Вставка
			// {PM}
			МассивДобавляемыхРеквизитов = упо_Интеграция.
				ПереопределитьПараметрыОбъектаXDTO(ОбъектМетаданных, ОбъектМетаданныхXDTO, Синонимы);
			ДобавитьОписаниеРеквизитов(
				ОбъектМетаданныхXDTO.attributes,
				МассивДобавляемыхРеквизитов,
				Синонимы);
			// {/PM}
			#КонецВставки

			Если ПолучатьВсе Или ПолучатьТабличныеЧасти Тогда

				Для Каждого ТабличнаяЧасть Из ОбъектМетаданных.ТабличныеЧасти Цикл

					Если ТабличнаяЧасть.Имя = "ДополнительныеРеквизиты"
						Или Лев(ТабличнаяЧасть.Имя, 7) = "Удалить"
						Или ТабличнаяЧасть.Реквизиты.Количество() = 0 Тогда
						Продолжить;
					КонецЕсли;

					ТабличнаяЧастьXDTO = СоздатьОбъектБИД("DMILMetadataTabularSection");
					ТабличнаяЧастьXDTO.name = ТабличнаяЧасть.Имя;
					ТабличнаяЧастьXDTO.synonym = ТабличнаяЧасть.Синоним;

					ДобавитьОписаниеРеквизитов(
					ТабличнаяЧастьXDTO.attributes,
					ТабличнаяЧасть.СтандартныеРеквизиты,
					Синонимы,
					Истина);
					ДобавитьОписаниеРеквизитов(
					ТабличнаяЧастьXDTO.attributes,
					ТабличнаяЧасть.Реквизиты,
					Синонимы);

					ТабличныеЧасти.Добавить(ТабличнаяЧастьXDTO);

				КонецЦикла;

			КонецЕсли;

			Если ПолучатьВсе Или ПолучатьПечатныеФормы Тогда
				ЗаполнитьПечатныеФормыОбъектаМетаданных(ОбъектМетаданныхXDTO);
			КонецЕсли;

			Если ПолучатьВсе Или ПолучатьПравилаИнтеграции Тогда
				ПодходящиеПравила =
				ИнтеграцияС1СДокументооборот3ВызовСервера.ПодходящиеПравилаИнтеграцииПоТипуОбъектаИС(ПолноеИмя);
				Для Каждого ДанныеПравила Из ПодходящиеПравила Цикл
					ПравилоИнтеграцииXDTO = СоздатьОбъектБИД("DMILIntegrationRule");
					ПравилоИнтеграцииXDTO.objectID = ПолучитьDMILObjectIDПоСсылке(ДанныеПравила.Ссылка);
					ПравилоИнтеграцииXDTO.objectTypeDM = ДанныеПравила.ТипОбъектаДО;
					ПравилоИнтеграцииXDTO.documentTypeID = ДанныеПравила.ИдентификаторВидаДокумента;
					ПравилоИнтеграцииXDTO.documentType = ДанныеПравила.ПредставлениеВидаДокумента;

					ПравилаИнтеграции.Добавить(ПравилоИнтеграцииXDTO);
				КонецЦикла;
			КонецЕсли;

			ОбъектыМетаданных.Добавить(ОбъектМетаданныхXDTO);

		КонецЦикла;

		Для Каждого Синоним Из Синонимы Цикл
			ОбъектМетаданныхXDTO = СоздатьОбъектБИД("DMILMetadataSynonym");
			ОбъектМетаданныхXDTO.name = Синоним.Ключ;
			ОбъектМетаданныхXDTO.synonym = Синоним.Значение;
			СинонимыОбъектов.Добавить(ОбъектМетаданныхXDTO);
		КонецЦикла;

		Возврат Ответ;

	Исключение

		Возврат ОписаниеОшибкиXDTO(
		НСтр("ru = 'Ошибка при получении структуры метаданных'"),
		ПолучитьОписаниеОшибки(ИнформацияОбОшибке()));

	КонецПопытки;

КонецФункции

// Экспортная обертка.
Функция упо_ПреобразоватьРеквизитОбъектаИСВОбъектXDTO(Прокси, ИмяРеквизита, ЗначениеРеквизита) Экспорт
	// {PM}
	ПреобразоватьРеквизитОбъектаИСВОбъектXDTO(Прокси, ИмяРеквизита, ЗначениеРеквизита);
	// {/PM}
КонецФункции

&ИзменениеИКонтроль("ПроверитьСоответствиеПравилИнтеграцииМетаданным")
Процедура упо_ПроверитьСоответствиеПравилИнтеграцииМетаданным() Экспорт

	Если Не ИспользоватьИнтеграцию() Тогда
		Возврат;
	КонецЕсли;

	ЗапросПравила = Новый Запрос(
		"ВЫБРАТЬ
		|	Правила.Ссылка
		|ИЗ
		|	Справочник.ПравилаИнтеграцииС1СДокументооборотом КАК Правила
		|ГДЕ
		|	НЕ ПометкаУдаления
		|	И ТипОбъектаИС <> """"");

	ВыборкаПравила = ЗапросПравила.Выполнить().Выбрать();
	Пока ВыборкаПравила.Следующий() Цикл

		ПравилоОбъект = ВыборкаПравила.Ссылка.ПолучитьОбъект(); // СправочникОбъект.ПравилаИнтеграцииС1СДокументооборотом
		Попытка
			ПравилоОбъект.Заблокировать();
		Исключение
			ЗаписьЖурналаРегистрации(
				ИнтеграцияС1СДокументооборотБазоваяФункциональность.ИмяСобытияЖурналаРегистрации(),
				УровеньЖурналаРегистрации.Ошибка,,,
				ОбработкаОшибок.ПодробноеПредставлениеОшибки(ИнформацияОбОшибке()));
			Продолжить;
		КонецПопытки;

		НужнаЗапись = Ложь;

		ОбъектМетаданных = Метаданные.НайтиПоПолномуИмени(ПравилоОбъект.ТипОбъектаИС); // ОбъектМетаданныхДокумент

		Если ОбъектМетаданных = Неопределено Тогда

			ТекстСообщения = СтрШаблон(
				НСтр("ru = 'Помечено на удаление правило для несуществующего объекта %1'",
					ОбщегоНазначения.КодОсновногоЯзыка()),
				ПравилоОбъект.ТипОбъектаИС);
			ЗаписьЖурналаРегистрации(
				ИнтеграцияС1СДокументооборотБазоваяФункциональность.ИмяСобытияЖурналаРегистрации(),
				УровеньЖурналаРегистрации.Ошибка,,,
				ТекстСообщения);

			ПравилоОбъект.ПометкаУдаления = Истина;
			НужнаЗапись = Истина;

		Иначе

			Для Каждого Правило Из ПравилоОбъект.ПравилаЗаполненияРеквизитовДО Цикл

				Если Правило.Вариант <> Перечисления.ВариантыПравилЗаполненияРеквизитов.РеквизитОбъекта
						Или Правило.ЭтоДополнительныйРеквизитИС
						Или Правило.ЭтоТаблица
						Или ЗначениеЗаполнено(Правило.Таблица) Тогда
					Продолжить;
				КонецЕсли;

				ПозицияТочки = СтрНайти(Правило.ИмяРеквизитаОбъектаИС, ".");
				Если ПозицияТочки = 0 Тогда
					ИмяРеквизитаОбъектаИС = Правило.ИмяРеквизитаОбъектаИС;
				Иначе
					ИмяРеквизитаОбъектаИС = Лев(Правило.ИмяРеквизитаОбъектаИС, ПозицияТочки - 1);
				КонецЕсли;

				Если ОбъектМетаданных.Реквизиты.Найти(ИмяРеквизитаОбъектаИС) = Неопределено
						И ИмяРеквизитаОбъектаИС <> "Представление" Тогда

					Найден = Ложь;
					Для Каждого СтандартныйРеквизит Из ОбъектМетаданных.СтандартныеРеквизиты Цикл
						Если СтандартныйРеквизит.Имя = ИмяРеквизитаОбъектаИС Тогда
							Найден = Истина;
							Прервать;
						КонецЕсли;
					КонецЦикла;

					#Вставка
					// {PM}
					упо_Интеграция.ПроверитьСоответствиеПравилИнтеграцииМетаданным(ОбъектМетаданных, ИмяРеквизитаОбъектаИС, Найден);
					// {/PM}
					#КонецВставки

					Если Не Найден Тогда

						ТекстСообщения = СтрШаблон(НСтр("ru = 'Очищено правило выгрузки для несуществующего реквизита %1'"),
							Правило.ИмяРеквизитаОбъектаИС);
						ЗаписьЖурналаРегистрации(
							ИнтеграцияС1СДокументооборотБазоваяФункциональность.ИмяСобытияЖурналаРегистрации(),
							УровеньЖурналаРегистрации.Ошибка,,
							ВыборкаПравила.Ссылка,
							ТекстСообщения);
						НужнаЗапись = Истина;

						Правило.Вариант = Неопределено;
						Правило.ИмяРеквизитаОбъектаИС = Неопределено;
						Правило.ЗначениеРеквизитаДО = ТекстСообщения;

					КонецЕсли;

				КонецЕсли;

			КонецЦикла;

			Для Каждого Правило Из ПравилоОбъект.ПравилаЗаполненияРеквизитовИС Цикл

				Если Правило.Вариант <> Перечисления.ВариантыПравилЗаполненияРеквизитов.РеквизитОбъекта
						Или Правило.ЭтоДополнительныйРеквизитИС
						Или Правило.ЭтоТаблица
						Или ЗначениеЗаполнено(Правило.Таблица) Тогда
					Продолжить;
				КонецЕсли;

				Если ОбъектМетаданных.Реквизиты.Найти(Правило.ИмяРеквизитаОбъектаИС) = Неопределено
						И Правило.ИмяРеквизитаОбъектаИС <> "Представление" Тогда

					Найден = Ложь;
					Для Каждого СтандартныйРеквизит Из ОбъектМетаданных.СтандартныеРеквизиты Цикл
						Если СтандартныйРеквизит.Имя = Правило.ИмяРеквизитаОбъектаИС Тогда
							Найден = Истина;
							Прервать;
						КонецЕсли;
					КонецЦикла;

					#Вставка
					// {PM}
					упо_Интеграция.ПроверитьСоответствиеПравилИнтеграцииМетаданным(ОбъектМетаданных, ИмяРеквизитаОбъектаИС, Найден);
					// {/PM}
					#КонецВставки

					Если Не Найден Тогда

						ТекстСообщения = СтрШаблон(НСтр("ru = 'Очищено правило загрузки для несуществующего реквизита %1'"),
							Правило.ИмяРеквизитаОбъектаИС);
						ЗаписьЖурналаРегистрации(
							ИнтеграцияС1СДокументооборотБазоваяФункциональность.ИмяСобытияЖурналаРегистрации(),
							УровеньЖурналаРегистрации.Ошибка,,
							ВыборкаПравила.Ссылка,
							ТекстСообщения);
						НужнаЗапись = Истина;

						Правило.Вариант = Неопределено;
						Правило.ИмяРеквизитаОбъектаИС = Неопределено;
						Правило.ЗначениеРеквизитаИС = ТекстСообщения;
						Правило.Обновлять = Ложь;

					КонецЕсли;

				КонецЕсли;

			КонецЦикла;

		КонецЕсли;

		Если НужнаЗапись Тогда
			ОбновлениеИнформационнойБазы.ЗаписатьДанные(ПравилоОбъект);
		КонецЕсли;

	КонецЦикла;

КонецПроцедуры

&После("ПриОпределенииНеобходимостиВыводитьКомандуПрисоединенныхФайловДО")
Процедура упо_ПриОпределенииНеобходимостиВыводитьКомандуПрисоединенныхФайловДО(Форма, Результат,
		СтандартнаяОбработка) Экспорт

	// {PM}
	упо_Интеграция.ПриОпределенииНеобходимостиВыводитьКомандуПрисоединенныхФайловДО(Форма, Результат,
	СтандартнаяОбработка);
	// {/PM}

КонецПроцедуры

&ИзменениеИКонтроль("ЗаполнитьСписокДоступныхРеквизитов")
Процедура упо_ЗаполнитьСписокДоступныхРеквизитов(Параметры, ИсточникиДоступныхПолей, КэшСКД)

	ИмяСпискаПолей = Параметры.ИмяСпискаПолей;
	УникальныйИдентификаторФормы = Параметры.УникальныйИдентификаторФормы;
	НастройкиСписка = Параметры.НастройкиСписка;
	ТекущийРеквизит = Параметры.ТекущийРеквизит;

	ДанныеКеша = Неопределено;
	ДоступныеРеквизиты = Неопределено;
	ТипУказан = ТипЗнч(ТекущийРеквизит) = Тип("СтрокаДереваЗначений") И ТекущийРеквизит.Тип <> Новый ОписаниеТипов();
	Если КэшСКД <> Неопределено И ТипУказан Тогда
		ОтборКэша = Новый Структура("ИмяСпискаПолей, ТипПоля", ИмяСпискаПолей, ТекущийРеквизит.Тип);
		ДанныеКеша = КэшСКД.НайтиСтроки(ОтборКэша);
		Если ДанныеКеша.Количество() > 0 Тогда
			ДоступныеРеквизиты = ДанныеКеша[0].ДоступныеПоля;
		КонецЕсли;
	КонецЕсли;

	Если ДоступныеРеквизиты = Неопределено Тогда
		КоллекцииДоступныхПолей = КоллекцииДоступныхПолей(ТекущийРеквизит, ИсточникиДоступныхПолей, НастройкиСписка, УникальныйИдентификаторФормы);
		ДоступныеРеквизиты = ДоступныеРеквизиты(КоллекцииДоступныхПолей);
		Если КэшСКД <> Неопределено И ТипУказан И ДанныеКеша.Количество() = 0 Тогда
			ДанныеКеша = КэшСКД.Добавить();
			ДанныеКеша.ИмяСпискаПолей = ИмяСпискаПолей;
			ДанныеКеша.ТипПоля = ТекущийРеквизит.Тип;
			ДанныеКеша.ДоступныеПоля = ДоступныеРеквизиты;
		КонецЕсли;
	КонецЕсли;

	КоллекцияРеквизитов = ПодчиненныеЭлементы(ТекущийРеквизит);
	ПолеСсылкаДобавлено = Ложь;
	Для Каждого ДоступныйРеквизит Из ДоступныеРеквизиты Цикл
		Если ДоступныйРеквизит.Имя = "Ссылка" Тогда
			Если ТипЗнч(ТекущийРеквизит) <> Тип("ДанныеФормыДерево") И ТипЗнч(ТекущийРеквизит) <> Тип("ДеревоЗначений")
				Или ПолеСсылкаДобавлено Тогда
				Продолжить;
			КонецЕсли;
			ПолеСсылкаДобавлено = Истина;
		КонецЕсли;

		#Вставка
		// {PM}
		Если ТипЗнч(ТекущийРеквизит) <> Тип("ДанныеФормыДерево") И ТипЗнч(ТекущийРеквизит) <> Тип("ДеревоЗначений") Тогда
			Если упо_Интеграция.КонструкторФормул_ПропуститьДобавлениеРеквизита(ТекущийРеквизит, ДоступныйРеквизит) Тогда
				Продолжить;
			Иначе
				упо_Интеграция.КонструкторФормул_КорректироватьЗаголовокРеквизита(ТекущийРеквизит, ДоступныйРеквизит);
			КонецЕсли;
		КонецЕсли;
		// {/PM}
		#КонецВставки

		Реквизит = КоллекцияРеквизитов.Добавить();
		ЗаполнитьЗначенияСвойств(Реквизит, ДоступныйРеквизит);

		Если Родитель(Реквизит) <> Неопределено Тогда
			Родитель = Родитель(Реквизит);
			Если Реквизит.ЭтоГруппа Тогда
				Реквизит.ПутьКДанным = Родитель.ПутьКДанным;
				Реквизит.ПредставлениеПутиКДанным = Строка(Родитель.ПредставлениеПутиКДанным);
			Иначе
				Если ЗначениеЗаполнено(Родитель.ПутьКДанным) Тогда
					Реквизит.ПутьКДанным = Родитель.ПутьКДанным + "." + Реквизит.Имя;
					Реквизит.ПредставлениеПутиКДанным = Строка(Родитель.ПредставлениеПутиКДанным) + "." + Реквизит.Заголовок;
				КонецЕсли;
			КонецЕсли;
		КонецЕсли;

		Если ДоступныйРеквизит.ЕстьПодчиненные Тогда
			ПодчиненныеЭлементы(Реквизит).Добавить();
		ИначеЕсли НастройкиСписка <> Неопределено И ЗначениеЗаполнено(НастройкиСписка.ПриОпределенииИсточниковДоступныхПолей) Тогда
			КоллекцииПолейРеквизита = КоллекцииДоступныхПолей(Реквизит, ИсточникиДоступныхПолей, НастройкиСписка, УникальныйИдентификаторФормы);
			Если ЗначениеЗаполнено(КоллекцииПолейРеквизита) И Не СтрНайти(Реквизит.ПутьКДанным, Реквизит.Имя + ".")
				И ЗначениеЗаполнено(КоллекцииПолейРеквизита[0].Элементы) Тогда
				ПодчиненныеЭлементы(Реквизит).Добавить();
			КонецЕсли;
		КонецЕсли;
	КонецЦикла;

КонецПроцедуры

&ИзменениеИКонтроль("ЕстьПодчиненныеЭлементы")
Функция упо_ЕстьПодчиненныеЭлементы(Знач ОписаниеПоля)

	#Вставка
	// {PM}
	ПолеСтрокой = Строка(ОписаниеПоля.Поле);
	Если СтрНайти(ПолеСтрокой, ".упо_СлужебнаяГруппаОтветственные.") > 0
		Или СтрНайти(ПолеСтрокой, ".упо_СлужебнаяГруппаПолномочия.") > 0
		Или СтрНайти(ПолеСтрокой, ".упо_СлужебнаяГруппаПроверкаНаличияПолномочий.") > 0 Тогда
		Возврат Ложь;
	КонецЕсли;
	// {/PM}
	#КонецВставки

	Если ОписаниеПоля.Папка Или ОписаниеПоля.Таблица Тогда
		Возврат Истина;
	КонецЕсли;

	Для Каждого Тип Из ОписаниеПоля.Тип.Типы() Цикл
		Если ОбщегоНазначения.ЭтоСсылка(Тип) 
			Или Тип = Тип("Дата") И ОписаниеПоля.Элементы.Количество() > 0 Тогда
			Возврат Истина;
		КонецЕсли; 
	КонецЦикла;

	#Вставка
	// {PM}
	Если ЗначениеЗаполнено(ОписаниеПоля.Элементы) Тогда
		Возврат Истина;
	КонецЕсли;
	// {/PM}
	#КонецВставки

	Возврат Ложь;

КонецФункции

